class ObservabilityCallback:
    """Purpose-built LLM observability platforms plug into a framework's
    callback mechanism (e.g. LangChain/LangGraph Runnables) with minimal
    code change, rather than requiring a rewrite of the chain itself."""

    def __init__(self, platform_client):
        self.client = platform_client

    def on_llm_start(self, prompt, **metadata):
        self.client.start_span(name="model_call", prompt=prompt, metadata=metadata)

    def on_llm_end(self, response, input_tokens, output_tokens):
        cost = self.client.estimate_cost(input_tokens, output_tokens)
        self.client.end_span(
            response=response,
            tokens={"in": input_tokens, "out": output_tokens},
            cost=cost,
        )

    def on_eval_score(self, trace_id, criterion, score):
        # Attaches an evaluation score (module 3) to a specific trace.
        self.client.attach_score(trace_id, criterion=criterion, score=score)


def build_traced_chain(chain, platform_client):
    callback = ObservabilityCallback(platform_client)
    return chain.with_config(callbacks=[callback])
```

`build_traced_chain` adds full observability to an existing chain through its callback configuration alone — no change to the chain's own logic — which is exactly the low-friction integration path this lesson describes.
